export const UI_STRINGS: Record<LanguageCode, Record<UiStringKey, string>> = {
  en: EN_STRINGS,
  bn: BN_STRINGS,
  hi: HI_STRINGS,
  ar: AR_STRINGS,
  es: ES_STRINGS,
  fr: FR_STRINGS,
};

export function t(
  lang: LanguageCode,
  key: UiStringKey,
  vars?: Record<string, string | number>
): string {
  const dict = UI_STRINGS[lang] ?? UI_STRINGS.en;
  let template = dict[key] ?? UI_STRINGS.en[key];
  if (!vars) return template;
  for (const [k, v] of Object.entries(vars)) {
    template = template.replace(new RegExp(`\\{${k}\\}`, 'g'), String(v));
  }
  return template;
}

