export function translateDepartmentName(
  lang: LanguageCode,
  slug: string,
  fallback: string
): string {
  if (lang === 'en') return fallback;
  return DEPARTMENT_TRANSLATIONS[slug]?.[lang]?.name ?? fallback;
}

export function translateDepartmentShortName(
  lang: LanguageCode,
  slug: string,
  fallback: string
): string {
  if (lang === 'en') return fallback;
  return DEPARTMENT_TRANSLATIONS[slug]?.[lang]?.shortName ?? fallback;
}

